	/** 
	 * jumpstart the process by instantiating2 Enterprise
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		enterpriseId = EnterpriseService.getEnterpriseInstance()
		.createEnterprise( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		EnterpriseService.getEnterpriseInstance()
				.createEnterprise( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.enterpriseSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Enterprise : " + successValue.getEnterpriseId());
							  if (successValue.getEnterpriseId().equals(enterpriseId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfEnterpriseList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Enterprise test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on enterprise consumed")
					);
			subscriber.enterpriseSubscribe( enterpriseId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Enterprise : " + successValue.getEnterpriseId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfEnterpriseList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on enterprise for enterpriseId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Enterprise. 
	 */
	protected Enterprise read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Enterprise" );

		Enterprise entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Enterprise with primary key" );
		msg.append( enterpriseId );
		
		EnterpriseFetchOneSummary fetchOneSummary = new EnterpriseFetchOneSummary( enterpriseId );

		try {
			entity = EnterpriseService.getEnterpriseInstance().getEnterprise( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Enterprise " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Enterprise.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Enterprise." );

		StringBuilder msg = new StringBuilder( "Failed to update a Enterprise : " );        
		Enterprise entity = read();
		UpdateEnterpriseCommand command = generateUpdateCommand();
		command.setEnterpriseId(entity.getEnterpriseId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Enterprise." );

			// for use later on...
			enterpriseId = entity.getEnterpriseId();

			EnterpriseService proxy = EnterpriseService.getEnterpriseInstance();  

			proxy.updateEnterprise( command ).get();

			LOGGER.info( "-- Successfully saved Enterprise - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + enterpriseId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Enterprise.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Enterprise." );

		Enterprise entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Enterprise with id " + enterpriseId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Enterprise with id " + enterpriseId );

			throw e;
		}

		try{
			EnterpriseService.getEnterpriseInstance().delete( new DeleteEnterpriseCommand( entity.getEnterpriseId() ) ).get();
			LOGGER.info( "-- Successfully deleted Enterprise with id " + enterpriseId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Enterprise with id " + enterpriseId );

			throw e;
		}
	}

	/**
	 * get all Enterprises.
	 */
	protected List<Enterprise> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Enterprises:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Enterprise : " );        
		List<Enterprise> collection  = new ArrayList<>();

		try {
			// call the static get method on the EnterpriseService
			collection = EnterpriseService.getEnterpriseInstance().getAllEnterprise();
			assertNotNull( collection, "An Empty collection of Enterprise was incorrectly returned.");
			
			// Now print out the values
			Enterprise entity = null;            
			Iterator<Enterprise> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getEnterpriseId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

